const archiveById = new Map(archiveDramas.map(work => [work.id, work]));
const aliases = { lookmheesonya: ['LMSY'], engfacharlotte: ['EngLot'], mablepangjie: ['BleJie'], namnoey: ['NamNoey'], bminenear: ['BMineNear'], atommer: ['AtomMer'] };

export const expandedCpProfiles = expandedPairDefinitions.map(([id, names, workIds, pairSource]) => {
  const works = workIds.map(workId => {
    const drama = archiveById.get(workId);
    if (!drama) throw new Error(`Unknown CP work: ${id}/${workId}`);
    return { id: drama.id, title: localizedWorkTitle({id: drama.id, title: drama.titleEn}, 'zh'), year: drama.year, source: drama.sourceUrl, ensemble: workId === 'girl-rules' };
  });
  const source = pairSource || works[0].source;
  const members = names.map(nickname => {
    const cast = archiveMainCastById[workIds[0]] || [];
    const fullName = cast.find(name => name.startsWith(`${nickname} `));
    if (!fullName) throw new Error(`Unresolved CP member: ${id}/${nickname}`);
    return { name: fullName, nickname, source, instagram: null, x: null };
  });
  const titles = works.map(work => work.title).join(' / ');
  const titlesFor = locale => works.map(work => localizedWorkTitle(work, locale)).join(' / ');
  return {
    id, names, aliases: aliases[id] || [], members, image: null, works, events: [], shops: [],
    intro: {
      zh: `${names.join(' 与 ')} 的共同作品：${titles}。从作品认识这对荧幕搭档。`,
      en: `Explore ${names.join(' and ')} through their shared screen work: ${titlesFor('en')}.`,
      th: `รู้จัก ${names.join(' และ ')} ผ่านผลงานที่แสดงร่วมกัน: ${titlesFor('th')}`,
    },
  };
});

